    private static String generateUrl(String scheme, int port, String hostname) {
        if (!hostname.startsWith("http")) {
            throw new IllegalArgumentException("Hostname must start with http");
        }

        try {
            InetAddress address = InetAddress.getByName(hostname);
            return scheme + "://" + address.getHostAddress() + ":" + port;
        } catch (UnknownHostException e) {
            throw new RuntimeException(e);
